mapper.insert:
insert into cm_user_goal_change(
    id,goal_id,user_id,change_type,before_data,after_data,reason,request_id,operator_id
) values(
    #{id},#{goalId},#{userId},'created',null,cast(#{afterData} as jsonb),null,#{requestId},#{operatorId}
)

insert into cm_idempotency_record(
    id,action_code,request_id,payload_hash,status,resource_type,resource_id,expires_time
) values(
    #{id},#{action},#{requestId},#{payloadHash},'processing','learning_goal',#{resourceId},#{expiresTime}
) on conflict do nothing

mapper.update:
update cm_idempotency_record
   set status='succeeded',response_status=200,response_body=cast(#{responseBody} as jsonb),update_time=now()
 where id=#{id}

mapper.select:
(select 'official' exam_batch_type, schedule.exam_start_date target_exam_date from cm_exam_schedule schedule
  join cm_exam_period period on period.id=schedule.exam_period_id
  where schedule.certification_id=#{certificationId} and period.status='published' and period.record_origin='official'
    and schedule.exam_start_date > #{today}
    and extract(year from schedule.exam_start_date)=#{targetExamYear} and extract(month from schedule.exam_start_date)=#{targetExamMonth}
  order by schedule.exam_start_date, schedule.id
  limit 1)
union all select 'estimated', null where not exists (
    select 1 from cm_exam_schedule schedule join cm_exam_period period on period.id=schedule.exam_period_id
     where schedule.certification_id=#{certificationId} and period.status='published' and period.record_origin='official'
       and schedule.exam_start_date > #{today} and extract(year from schedule.exam_start_date)=#{targetExamYear}
       and extract(month from schedule.exam_start_date)=#{targetExamMonth}
)

select schedule.exam_start_date from cm_exam_schedule schedule
  join cm_exam_period period on period.id=schedule.exam_period_id
 where schedule.certification_id=#{certificationId} and period.status in ('published', 'superseded')
   and extract(year from schedule.exam_start_date)=#{targetExamYear}
   and extract(month from schedule.exam_start_date)=#{targetExamMonth}
 order by schedule.exam_start_date desc, schedule.id desc limit 1
